package com.danil.blackswordsman;
import java.io.*;
/** Compile-time content baking: Android never constructs toy geometry during drawing. */
public final class BakeAssets {
 public static void main(String[] args)throws Exception{File definition=new File(args[0],"items.tsv");if(!definition.exists()){java.io.Writer writer=new java.io.OutputStreamWriter(new java.io.FileOutputStream(definition),"UTF-8");writer.write("# id\tfamily\tvariant\ta\tb\tname\thx\thy\thz\tmass\n");for(SurrealCatalog.Item item:SurrealCatalog.ITEMS)writer.write(item.id+"\t"+item.family+"\t"+item.variant+"\t"+item.a+"\t"+item.b+"\t"+item.name+"\t"+item.hx+"\t"+item.hy+"\t"+item.hz+"\t"+item.mass+"\n");writer.close();}SurrealCatalog.load(new FileInputStream(definition));File dir=new File(args[0],"meshes");dir.mkdirs();for(int id=0;id<250;id++)for(int lod=0;lod<2;lod++){ToyGeometry.Data d=id<240?ToyGeometry.build(SurrealCatalog.ITEMS[id],lod==1):ToyGeometry.pickup(id-240,lod==1);DataOutputStream out=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(new File(dir,id+"-"+lod+".bin"))));out.writeInt(d.vertices.length);out.writeInt(d.indices.length);for(float f:d.vertices)out.writeFloat(f);for(short s:d.indices)out.writeShort(s);out.close();}SurfaceLibrary.bake(new File(args[0]));File flora=new File(args[0],"flora");flora.mkdirs();for(int id=0;id<48;id++)for(int lod=0;lod<2;lod++){ToyGeometry.Data d=FloraGeometry.build(id,lod==1);File dest=new File(flora,id+"-"+lod+".bin"),part=new File(dest+".part");DataOutputStream out=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(part)));out.writeInt(d.vertices.length);out.writeInt(d.indices.length);for(float f:d.vertices)out.writeFloat(f);for(short i:d.indices)out.writeShort(i);out.close();if(!part.renameTo(dest))throw new IOException("Flora rename failed");}System.out.println("Baked 500 toy/pickup meshes and 24 material maps (512 square)");}
}
